package com.quizarena.dao;
import com.quizarena.database.Database; import com.quizarena.model.Question; import java.sql.*; import java.util.*;
public class QuestionDao {
 public List<Question> random(String category,String difficulty,int count) throws SQLException {String sql="SELECT q.id,q.question_text,q.option_a,q.option_b,q.option_c,q.option_d,q.correct_option FROM questions q JOIN categories c ON c.id=q.category_id WHERE c.name=? AND q.difficulty=? ORDER BY RAND() LIMIT ?"; try(Connection c=Database.open();PreparedStatement p=c.prepareStatement(sql)){p.setString(1,category);p.setString(2,difficulty);p.setInt(3,count);try(ResultSet r=p.executeQuery()){List<Question> out=new ArrayList<>();while(r.next())out.add(new Question(r.getLong(1),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7).charAt(0)));return out;}}}
 public void add(String category,String difficulty,String text,String a,String b,String cOption,String d,char correct) throws SQLException {try(Connection c=Database.open()){c.setAutoCommit(false);try(PreparedStatement cat=c.prepareStatement("INSERT INTO categories(name) VALUES(?) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id)",Statement.RETURN_GENERATED_KEYS);PreparedStatement q=c.prepareStatement("INSERT INTO questions(category_id,difficulty,question_text,option_a,option_b,option_c,option_d,correct_option) VALUES(LAST_INSERT_ID(),?,?,?,?,?,?,?)")){cat.setString(1,category);cat.executeUpdate();q.setString(1,difficulty);q.setString(2,text);q.setString(3,a);q.setString(4,b);q.setString(5,cOption);q.setString(6,d);q.setString(7,String.valueOf(correct));q.executeUpdate();c.commit();}catch(SQLException e){c.rollback();throw e;}}}
}
